export function localApproachPool(firstThree: BatchChallenge[]): Stage[] {
  const reused = firstThree.flatMap(challenge => challenge.stages.map(stage => ({
    ...stage,
    area: challenge.region,
    sources: ["Owner-supplied, previously approved first-batch approach estimate"],
    evidenceNote: [stage.evidenceNote, `Reused unchanged from ${challenge.sourceId}. The published-source bibliography for this original owner-supplied estimate was not included in the handover; this is not a fresh independent measurement.`].filter(Boolean).join(" "),
  })));
  // Ordinary mountain-path warnings must not automatically label a walk as
  // expert scrambling. Reused technical approaches retain their old grading.
  return [...reused, ...PUBLISHED_LOCAL_APPROACHES.map(stage => ({ ...stage, difficulty: "Hard" }))];
}

/** Deterministic curation aid, not a completion threshold. Minimise ascent
 * difference first; prefer fewer, more substantial summits within the same
 * five-percentage-point fit band. The selected set is persisted as a revision
 * snapshot by existing start/save flows, never recomputed for saved plans.
 */
export function chooseStages(pool: Stage[], areas: string[], targetAscent: number): Stage[] {
  const eligible = pool.filter(stage => areas.includes(stage.area!));
  if (eligible.length > 20) throw new Error("Unbounded local curation pool");
  let best: Stage[] = [], bestScore = Infinity;
  for (let mask = 1; mask < 2 ** eligible.length; mask++) {
    const selected = eligible.filter((_, index) => mask & (1 << index));
    const gain = selected.reduce((sum, stage) => sum + stage.ascentM, 0);
    const difference = Math.abs(gain - targetAscent) / targetAscent;
    const score = Math.floor((difference + 1e-9) / 0.05) * 100
      + selected.length * 2 + difference;
    if (score < bestScore) { best = selected; bestScore = score; }
  }
  return best.sort((a, b) => b.ascentM - a.ascentM || a.id.localeCompare(b.id));
}
